    {w:"Apr 13",v:114},
    {w:"Apr 20",v:116},
    {w:"Apr 27",v:113},
    {w:"May 4",v:119},
    {w:"May 6",v:109},
    {w:"May 11",v:112},
    {w:"May 15",v:107},
    {w:"May 18",v:111},
    {w:"May 20",v:104},
    {w:"May 22",v:104.52}
  ];
  var dips = [
    {i:6,label:"Apr 8 ceasefire"},
    {i:11,label:"May 6 Rubio"},
    {i:15,label:"May 20 Rubio"}
  ];
  var W=680, H=300;
  var margin={left:62,right:24,top:18,bottom:46};
  var PW=W-margin.left-margin.right;
  var PH=H-margin.top-margin.bottom;
  var n=data.length;
  var minV=65, maxV=132;
  function xp(i){return margin.left + i/(n-1)*PW;}
  function yp(v){return margin.top + (1-(v-minV)/(maxV-minV))*PH;}
  var svg=document.createElementNS("http://www.w3.org/2000/svg","svg");
  svg.setAttribute("viewBox","0 0 "+W+" "+H);
  svg.setAttribute("width","100%");
  function el(tag,attrs){
    var e=document.createElementNS("http://www.w3.org/2000/svg",tag);
    for(var k in attrs)e.setAttribute(k,attrs[k]);
    return e;
  }
  function txt(s,attrs){
    var t=el("text",attrs);
    t.textContent=s;
    return t;
  }
  // Gridlines
  var yticks=[75,85,95,105,115,125];
  yticks.forEach(function(v){
    var y=yp(v);
    svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:y,y2:y,stroke:"#ececec","stroke-width":"0.5"}));
    svg.appendChild(txt("$"+v,{x:margin.left-6,y:y+3,fill:"#aaa","font-size":"8.5","text-anchor":"end","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  });
  // Axes
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:margin.top+PH,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":"1"}));
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left,y1:margin.top,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":"1"}));
  // Pre-war floor band
  svg.appendChild(el("rect",{x:margin.left,y:yp(75),width:PW,height:yp(65)-yp(75),fill:"#2e7d32",opacity:"0.07"}));
  svg.appendChild(txt("PRE-WAR RANGE",{x:margin.left+8,y:yp(71),"font-size":"7","font-weight":"700",fill:"#2e7d32","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  // Line
  var pts=data.map(function(d,i){return xp(i)+","+yp(d.v);}).join(" ");
  svg.appendChild(el("polyline",{points:pts,fill:"none",stroke:"#4a5568","stroke-width":"2"}));
  // Area fill
  var apts=data.map(function(d,i){return xp(i)+","+yp(d.v);}).join(" ");
  var aClose=xp(n-1)+","+yp(minV)+" "+xp(0)+","+yp(minV);
  svg.appendChild(el("polygon",{points:apts+" "+aClose,fill:"#4a5568",opacity:"0.07"}));
  // Dip event markers
  dips.forEach(function(ev,di){
    var ex=xp(ev.i);
    var ey=yp(data[ev.i].v);
    svg.appendChild(el("line",{x1:ex,x2:ex,y1:margin.top,y2:margin.top+PH,stroke:"#1a3560","stroke-width":"1","stroke-dasharray":"2,3",opacity:"0.5"}));
    var crowded=di>0 && Math.abs(xp(dips[di-1].i)-ex)<60;
    var anchor=crowded?"end":"start";
    var ox=crowded?-4:4;
    var oy=crowded?margin.top+50:margin.top+20;
    svg.appendChild(txt(ev.label,{x:ex+ox,y:oy,"font-size":"7","font-weight":"700",fill:"#1a3560","text-anchor":anchor,"font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  });
  // Reference line $90 structural floor
  var refV=90; var refY=yp(refV);
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:refY,y2:refY,stroke:"#2e7d32","stroke-dasharray":"3,3","stroke-width":"1"}));
  if(Math.abs(refV-data[n-1].v)/data[n-1].v >= 0.03){
    svg.appendChild(txt("$90 physical floor est.",{x:650,y:refY-3,fill:"#2e7d32","font-size":"7.5","text-anchor":"end","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  }
  // Dots on data points
  data.forEach(function(d,i){
    svg.appendChild(el("circle",{cx:xp(i),cy:yp(d.v),r:"2.5",fill:"#4a5568"}));
  });
  // Gold pill at last point
  var lastX=xp(n-1); var lastY=yp(data[n-1].v);
  var pillW=62; var pillH=16;
  var pillX=lastX-pillW-6;
  if(pillX<margin.left)pillX=lastX+6;
  var pillY=lastY-pillH/2;
  svg.appendChild(el("circle",{cx:lastX,cy:lastY,r:4,fill:"#4a5568"}));
  svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,rx:"3",fill:"#e8a825"}));
  svg.appendChild(txt("$104.52",{x:pillX+pillW/2,y:pillY+pillH/2+3.5,"text-anchor":"middle","font-size":"9","font-weight":"700",fill:"#111","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  // X axis labels
  var xshow=[0,3,6,9,12,16];
  xshow.forEach(function(i){
    if(i<n){
      svg.appendChild(txt(data[i].w,{x:xp(i),y:margin.top+PH+14,fill:"#999","font-size":"8","text-anchor":"middle","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
    }
  });
  var container=document.currentScript?document.currentScript.parentNode:null;
  if(container)container.appendChild(svg);
})();
