  var pillX=lastX-pillW-6;
  if(pillX<margin.left)pillX=lastX+6;
  var pillY=lastY-pillH/2;
  svg.appendChild(el("circle",{cx:lastX,cy:lastY,r:4,fill:"#4a5568"}));
  svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,rx:"3",fill:"#e8a825"}));
  svg.appendChild(txt("34,410",{x:pillX+pillW/2,y:pillY+pillH/2+3.5,"text-anchor":"middle","font-size":"9","font-weight":"700",fill:"#111","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
  // X axis labels
  [0,3,6,9,12,15].forEach(function(i){
    if(i<n){
      svg.appendChild(txt(data[i].w,{x:xp(i),y:margin.top+PH+14,fill:"#999","font-size":"8","text-anchor":"middle","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));
    }
